            shape: 'one sentence', expect: 'A harvest dance may become a nightly show for hotel guests (also accepted: a temple festival may turn into a daily performance for tour groups)',
            accept: [['dance|festival|ceremony|ritual|custom|tradition|song'], ['(may|might|could|can) (become|turn into|be reduced to|degenerate into|end up as)'], ['show|performance|spectacle|entertainment'], ['guests|tourists|visitors|tour groups|hotels?']],
            reject: [{ re: 'degenerate to\\b', hint: 'Check the preposition after "degenerate".' },
              { re: 'inevitably|\\balways\\b|will become', hint: 'Overclaimed: keep to one case and a hedge.' },
              { re: 'enrich|improv|strengthen', hint: 'That contradicts the harm you are showing.' }],
